import type {
  ProviderBCommitBatch,
  ProviderBReservationRow,
  ProviderBStorage,
  ProviderBStockRow,
  Reservation,
  Service,
  ServiceResponse,
  Stock,
} from "./types";
import { error } from "./reservation";
import {
  decodeCanonicalNonnegativeDecimal,
  encodeCanonicalNonnegativeDecimal,
  isId,
  isQuantity,
  isRecord,
  isRevision,
} from "./validation";

type Command =
  | { op: "getAvailability"; sku: string }
  | { op: "getReservation"; reservationId: string }
  | { op: "reserve"; reservationId: string; sku: string; quantity: number };

type ReadOutcome =
  | { kind: "found"; value: unknown }
  | { kind: "missing" }
  | { kind: "unavailable" };

function parseCommand(raw: unknown): Command | undefined {
  if (!isRecord(raw)) return undefined;
  switch (raw.op) {
    case "getAvailability":
      return isId(raw.sku) ? { op: raw.op, sku: raw.sku } : undefined;
    case "getReservation":
      return isId(raw.reservationId)
        ? { op: raw.op, reservationId: raw.reservationId } : undefined;
    case "reserve":
      return isId(raw.reservationId) && isId(raw.sku) && isQuantity(raw.quantity)
        ? { op: raw.op, reservationId: raw.reservationId, sku: raw.sku, quantity: raw.quantity }
        : undefined;
    default:
      return undefined;
  }
}

function reservationResponse(status: 200 | 201, reservation: Reservation): ServiceResponse {
  return {
    status,
    body: {
      reservationId: reservation.reservationId,
      sku: reservation.sku,
      quantity: reservation.quantity,
    },
  };
}

function decodeProviderBStock(value: unknown, requestedSku: string): Stock | undefined {
  if (!isRecord(value) || value.itemKey !== requestedSku) return undefined;
  const totalUnits = decodeCanonicalNonnegativeDecimal(value.onHandText);
  const reservedUnits = decodeCanonicalNonnegativeDecimal(value.heldText);
  const revision = decodeCanonicalNonnegativeDecimal(value.revisionText);
  if (totalUnits === undefined || reservedUnits === undefined || revision === undefined ||
      totalUnits > 1_000_000 || reservedUnits > 1_000_000 || reservedUnits > totalUnits ||
      !isRevision(revision)) {
    return undefined;
  }
  return { sku: value.itemKey, totalUnits, reservedUnits, revision };
}

function decodeProviderBReservation(value: unknown, requestedReservationId: string): Reservation | undefined {
  if (!isRecord(value) || value.bookingKey !== requestedReservationId || !isId(value.itemKey)) return undefined;
  const quantity = decodeCanonicalNonnegativeDecimal(value.unitsText);
  if (quantity === undefined || !isQuantity(quantity)) return undefined;
  return {
    reservationId: value.bookingKey,
    sku: value.itemKey,
    quantity,
  };
}

function toStockRow(stock: Stock): ProviderBStockRow {
  return {
    itemKey: stock.sku,
    onHandText: encodeCanonicalNonnegativeDecimal(stock.totalUnits),
    heldText: encodeCanonicalNonnegativeDecimal(stock.reservedUnits),
    revisionText: encodeCanonicalNonnegativeDecimal(stock.revision),
  };
}

function toReservationRow(reservation: Reservation): ProviderBReservationRow {
  return {
    bookingKey: reservation.reservationId,
    itemKey: reservation.sku,
    unitsText: encodeCanonicalNonnegativeDecimal(reservation.quantity),
  };
}

async function readProviderB(
  storage: ProviderBStorage,
  collection: "inventory" | "reservations",
  key: string,
): Promise<ReadOutcome> {
  try {
    const envelope = await storage.read({ collection, key });
    if (!isRecord(envelope) || typeof envelope.ok !== "boolean") return { kind: "unavailable" };
    if (envelope.ok) {
      return Object.hasOwn(envelope, "value") && envelope.value !== null
        ? { kind: "found", value: envelope.value }
        : { kind: "unavailable" };
    }
    if (!isRecord(envelope.error) || typeof envelope.error.reason !== "string") return { kind: "unavailable" };
    return envelope.error.reason === "NO_SUCH_KEY" ? { kind: "missing" } : { kind: "unavailable" };
  } catch {
    return { kind: "unavailable" };
  }
}

function availabilityResponse(stock: Stock): ServiceResponse {
  return {
    status: 200,
    body: {
      sku: stock.sku,
      totalUnits: stock.totalUnits,
      reservedUnits: stock.reservedUnits,
      availableUnits: stock.totalUnits - stock.reservedUnits,
    },
  };
}

export function createProviderBReservationService({ storage }: { storage: ProviderBStorage }): Service {
  return {
    async handle(raw): Promise<ServiceResponse> {
      const command = parseCommand(raw);
      if (command === undefined) return error(400, "invalid_command");

      if (command.op === "getAvailability") {
        const stockRead = await readProviderB(storage, "inventory", command.sku);
        if (stockRead.kind === "missing") return error(404, "stock_not_found");
        if (stockRead.kind === "unavailable") return error(500, "storage_unavailable");
        const stock = decodeProviderBStock(stockRead.value, command.sku);
        return stock === undefined ? error(500, "storage_unavailable") : availabilityResponse(stock);
      }

      const reservationRead = await readProviderB(storage, "reservations", command.reservationId);
      if (reservationRead.kind === "unavailable") return error(500, "storage_unavailable");
      const existing = reservationRead.kind === "found"
        ? decodeProviderBReservation(reservationRead.value, command.reservationId)
        : undefined;
      if (reservationRead.kind === "found" && existing === undefined) return error(500, "storage_unavailable");

      if (command.op === "getReservation") {
        return existing === undefined ? error(404, "reservation_not_found") : reservationResponse(200, existing);
      }

      if (existing !== undefined) {
        return existing.sku === command.sku && existing.quantity === command.quantity
          ? reservationResponse(200, existing)
          : error(409, "reservation_conflict");
      }

      const stockRead = await readProviderB(storage, "inventory", command.sku);
      if (stockRead.kind === "missing") return error(404, "stock_not_found");
      if (stockRead.kind === "unavailable") return error(500, "storage_unavailable");
      const stock = decodeProviderBStock(stockRead.value, command.sku);
      if (stock === undefined) return error(500, "storage_unavailable");
      if (stock.totalUnits - stock.reservedUnits < command.quantity) {
        return error(409, "insufficient_stock");
      }

      const nextRevision = stock.revision + 1;
      if (!isRevision(nextRevision)) return error(500, "storage_unavailable");

      const reservation: Reservation = {
        reservationId: command.reservationId,
        sku: command.sku,
        quantity: command.quantity,
      };
      const nextStock: Stock = {
        ...stock,
        reservedUnits: stock.reservedUnits + command.quantity,
        revision: nextRevision,
      };
      const reservationRow = toReservationRow(reservation);
      const batch: ProviderBCommitBatch = {
        expectedRevisionText: encodeCanonicalNonnegativeDecimal(stock.revision),
        stockRow: toStockRow(nextStock),
        reservationRow,
        outboxRows: [{
          key: "reservation.created:" + reservation.reservationId,
          category: "reservation",
          name: "created",
          payload: {
            bookingKey: reservationRow.bookingKey,
            itemKey: reservationRow.itemKey,
            unitsText: reservationRow.unitsText,
          },
        }],
      };

      try {
        const outcome = await storage.commitBatch(batch);
        if (outcome === "revision_conflict") return error(409, "commit_conflict");
        if (outcome !== "applied") return error(500, "storage_unavailable");
        return reservationResponse(201, reservation);
      } catch {
        return error(500, "storage_unavailable");
      }
    },
  };
}

